20	export const Rooms: FC<Props> = ({ search }) => {
21	  const activeFilter = useAtomValue(SharedAtoms.activeFilter);
22	  const securityFilter = useAtomValue(SharedAtoms.securityFilter);
23	  const rooms = useAtomValue(MatrixAtoms.roomList);
24	  const roomInfoMap = useAtomValue(MatrixAtoms.roomInfoMap);
25	  const isLoading = useAtomValue(MatrixAtoms.roomListLoading);
26	  const filteredRooms = useMemo(() => {
27	    const filtered = rooms.filter((room) => {
28	      if (!room?.displayName()?.toLowerCase()?.includes(search.toLowerCase()))
29	        return false;
30	
31	      // For now there is no secure chats, so we show all chats
32	      if (securityFilter === "secure") return false;
33	
34	      if (securityFilter === "unsecure") return true;
35	
36	      return true;
37	    });
38	
39	    if (activeFilter === "all") return filtered;
40	
41	    if (activeFilter === "unread") {
42	      return filtered.filter((room) => {
43	        const info = roomInfoMap.get(room.id());
44	        return !!Number(info?.numUnreadNotifications) || !!info?.isMarkedUnread;
45	      });
46	    }
47	
48	    if (activeFilter === "favorites") {
49	      return filtered.filter(
50	        (room) => !!roomInfoMap.get(room.id())?.isFavourite,
51	      );
52	    }
53	
54	    if (activeFilter === "direct") {
55	      return filtered.filter((room) => !!roomInfoMap.get(room.id())?.isDirect);
56	    }
57	
58	    if (activeFilter === "rooms") {
59	      return filtered.filter((room) => {
60	        const info = roomInfoMap.get(room.id());
61	        return !info?.isDirect && room.membership() !== Membership.Invited;
62	      });
63	    }
64	
65	    if (activeFilter === "invites") {
66	      return filtered.filter(
67	        (room) => room.membership() === Membership.Invited,
68	      );
69	    }
70	
71	    return filtered;
72	  }, [search, rooms, roomInfoMap, activeFilter, securityFilter]);
73	
74	  const emptyText = useMemo(() => {
75	    if (activeFilter === "unread") return "No Unread Messages";
76	    if (activeFilter === "favorites") return "No Favorite Rooms";
77	    if (activeFilter === "direct") return "No Direct Messages";
78	    if (activeFilter === "rooms") return "No Rooms Found";
79	    if (activeFilter === "invites") return "No Pending Invites";
80	    return "No Messages Found";
81	  }, [activeFilter]);
82	
83	  const keyExtractor = useCallback((item: RoomInterface) => item.id(), []);
84	
85	  const renderItem = useCallback<ListRenderItem<RoomInterface>>(
86	    ({ item }) => <RoomsListItem room={item} />,
87	    [],
88	  );
89	
90	  const listEmptyComponent = useMemo(
91	    () => (
92	      <Block
93	        align="center"
94	        justify="center"
95	        paddings={20}
96	        margins={{ marginVertical: "auto" }}
97	      >
98	        <Image
99	          source={require("assets/images/envelope.png")}
100	          width={100}
101	          height={100}
102	        />
103	        <Text
104	          size={TextSize.large}
105	          textAlign="center"
106	          margins={{ marginBottom: 8, marginTop: 40 }}
107	        >
108	          {emptyText}
109	        </Text>
110	      </Block>
111	    ),
112	    [emptyText],
113	  );
114	
115	  if (isLoading && !rooms.length) return <Loading text="Syncing..." />;
116	
117	  if (!rooms.length) return null;
118	
119	  return (
120	    <FlashList
121	      data={filteredRooms}
122	      keyExtractor={keyExtractor}
123	      renderItem={renderItem}
124	      ListEmptyComponent={listEmptyComponent}
125	    />
126	  );
127	};
