43	const formatTimestamp = (timestamp: bigint | undefined) => {
44	  if (!timestamp) return "";
45	
46	  const date = new Date(Number(Number(timestamp)));
47	
48	  if (isToday(date)) return format(date, "HH:mm");
49	
50	  if (isYesterday(date)) return "Yesterday";
51	
52	  if (isThisWeek(date)) return format(date, "EEEE");
53	
54	  return format(date, "d. M. yyyy.");
55	};
